.about-grid{display:grid;grid-template-columns:1fr 1fr;gap:8vw;align-items:end} .process{display:grid;gap:1px;background:rgba(255,255,255,.18)} .process div{background:rgba(1,27,18,.82);padding:19px;font-size:13px;display:flex;justify-content:space-between} .process b{color:var(--lime)}
.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:8vw} .contact-card{border:1px solid rgba(255,255,255,.2);padding:32px;background:rgba(1,27,18,.68);backdrop-filter:blur(12px)} .contact-card label{display:block;font-size:10px;font-weight:800;letter-spacing:.08em;margin:16px 0 7px} .contact-card input,.contact-card textarea,.contact-card select{width:100%;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.2);color:white;padding:13px} .contact-card textarea{min-height:110px} .contact-card button{width:100%;margin-top:18px;border:0;background:var(--lime);color:#092016;padding:16px;font-weight:900}
