@media(max-width:900px){.nav{display:none}.hero{padding-top:110px}.hero-note{position:static;text-align:left;margin-top:35px}.scene-inner,.about-grid,.contact-grid{grid-template-columns:1fr;gap:50px}.visual{justify-content:flex-start}.project-grid{grid-template-columns:1fr 1fr}}
